INSERT INTO `oc_product_description` (`product_id`, `language_id`, `name`, `description`, `tag`, `meta_title`, `meta_description`, `meta_keyword`) VALUES
(118, 1, 'BLOCK-PRINTED LINEN NAPKIN (SET OF 2) - DOT & GRID - Green', '<p>Inspired by the quiet charm of country living, these hand block printed table napkins bring warmth and artisanal beauty to your dining experience. Each piece is thoughtfully crafted in 100% European linen, of 40&#039;s Thread count. showcasing the subtle elegance and natural texture of premium fabric.<br />\n<br />\nHandmade in small batches by skilled artisans, every napkin carries the unique character of traditional block printing.<br />\n<br />\nPerfect for everyday dining or special gatherings, this Set of 2 adds a timeless, understated sophistication to your table setting.<br />\n<br />\nDetails:<br />\nSize: 18&quot; x 18&quot;<br />\nMaterial: 100% Linen<br />\n<br />\nCare Instructions:<br />\nMachine wash cold on a gentle cycle with like colors. Lay flat to dry or tumble dry on low. Iron on reverse side for best results.<br />\n<br />\nMade in India</p>', 'ready', 'BLOCK-PRINTED LINEN NAPKIN (SET OF 2) - DOT & GRID - Green', 'Inspired by the quiet charm of country living, these hand block printed table napkins bring warmth and artisanal beauty to your dining experience. Each piece is thoughtfully crafted in 100% European linen, of 40\'s Thread count. showcasing the subtle elega', 'Dinner & Cloth Napkin'),
(119, 1, 'BLOCK-PRINTED LINEN NAPKIN (SET OF 2) - DOT & GRID - Pink', '<p>Inspired by the quiet charm of country living, these hand block printed table napkins bring warmth and artisanal beauty to your dining experience. Each piece is thoughtfully crafted in 100% European linen, of 40&#039;s Thread count. showcasing the subtle elegance and natural texture of premium fabric.<br />\n<br />\nHandmade in small batches by skilled artisans, every napkin carries the unique character of traditional block printing.<br />\n<br />\nPerfect for everyday dining or special gatherings, this Set of 2 adds a timeless, understated sophistication to your table setting.<br />\n<br />\nDetails:<br />\nSize: 18&quot; x 18&quot;<br />\nMaterial: 100% Linen<br />\n<br />\nCare Instructions:<br />\nMachine wash cold on a gentle cycle with like colors. Lay flat to dry or tumble dry on low. Iron on reverse side for best results.<br />\n<br />\nMade in India</p>', 'ready', 'BLOCK-PRINTED LINEN NAPKIN (SET OF 2) - DOT & GRID - Pink', 'Inspired by the quiet charm of country living, these hand block printed table napkins bring warmth and artisanal beauty to your dining experience. Each piece is thoughtfully crafted in 100% European linen, of 40\'s Thread count. showcasing the subtle elega', 'Dinner & Cloth Napkin'),
(120, 1, 'EMBROIDED SCALLOPED NAPKIN (SET OF 2) - ROSE', '<p>Thoughtfully crafted in natural fibers, this napkin set brings a quiet sense of warmth and refinement to your table. The solid hue is elevated by a delicately scalloped edge, adding a soft, graceful accent to everyday dining and special gatherings alike.<br />\n<br />\nVersatile and timeless, these napkins pair effortlessly with a variety of table settings—layer them with ceramics, glassware, or wood for a look that feels both relaxed and considered. The natural texture of linen enhances their appeal, softening beautifully with every wash.<br />\n<br />\nMade in small batches by master artisans, each piece reflects careful craftsmanship and enduring quality.<br />\n<br />\nPacked as a set of 2.<br />\n<br />\nSize: 18&quot; x 18&quot;<br />\nMaterial: 100% Linen<br />\n<br />\nCare Instructions: Machine wash cold on a gentle cycle with like colors. Do not bleach. Lay flat to dry or tumble dry low. Warm iron as needed.</p>', 'ready', 'EMBROIDED SCALLOPED NAPKIN (SET OF 2) - ROSE', 'Thoughtfully crafted in natural fibers, this napkin set brings a quiet sense of warmth and refinement to your table. The solid hue is elevated by a delicately scalloped edge, adding a soft, graceful accent to everyday dining and special gatherings alike.\n', 'Dinner & Cloth Napkin'),
