INSERT INTO `oc_product_description` (`product_id`, `language_id`, `name`, `description`, `tag`, `meta_title`, `meta_description`, `meta_keyword`) VALUES
(554, 1, 'BLOCK-PRINTED ROUND DESK TRAY SET - MINT-ROSE RHEA', '<p>Thoughtfully designed to keep your everyday essentials in place, this compact tray is perfect for organizing pencils, notes, keys, or jewelry. Whether styled on a desk, bedside, or entryway, it adds both function and understated elegance to your space.<br />\n<br />\nRecycled Cotton Handmade Paper Tray Sets are made by Master Artisans who have been creating vintage-style boxes and cartonnage products for generations in Jaipur. The paper design is block printed and produced in Small Batches only. Designed to Inspire a home filled with Artisanal Slow Living Objects.<br />\n<br />\n Set of Nested Small and Large Trays <br />\n<br />\nSize : Large - 4.5&quot; x 9&quot; x 1&quot;<br />\nSmall - 4&quot; X 4&quot; X 0.6&quot;<br />\n<br />\nMaterial: 100% Recycled Cotton Paper<br />\n<br />\nMade in India</p>', 'ready', 'BLOCK-PRINTED ROUND DESK TRAY SET - MINT-ROSE RHEA', 'Thoughtfully designed to keep your everyday essentials in place, this compact tray is perfect for organizing pencils, notes, keys, or jewelry. Whether styled on a desk, bedside, or entryway, it adds both function and understated elegance to your space.\n\nR', 'Desk Tray'),
(555, 1, 'BLOCK-PRINTED ROUND DESK TRAY SET - MINT-SKY RHEA', '<p>Thoughtfully designed to keep your everyday essentials in place, this compact tray is perfect for organizing pencils, notes, keys, or jewelry. Whether styled on a desk, bedside, or entryway, it adds both function and understated elegance to your space.<br />\n<br />\nRecycled Cotton Handmade Paper Tray Sets are made by Master Artisans who have been creating vintage-style boxes and cartonnage products for generations in Jaipur. The paper design is block printed and produced in Small Batches only. Designed to Inspire a home filled with Artisanal Slow Living Objects.<br />\n<br />\n Set of Nested Small and Large Trays <br />\n<br />\nSize : Large - 4.5&quot; x 9&quot; x 1&quot;<br />\nSmall - 4&quot; X 4&quot; X 0.6&quot;<br />\n<br />\nMaterial: 100% Recycled Cotton Paper<br />\n<br />\nMade in India</p>', 'ready', 'BLOCK-PRINTED ROUND DESK TRAY SET - MINT-SKY RHEA', 'Thoughtfully designed to keep your everyday essentials in place, this compact tray is perfect for organizing pencils, notes, keys, or jewelry. Whether styled on a desk, bedside, or entryway, it adds both function and understated elegance to your space.\n\nR', 'Desk Tray'),
(556, 1, 'BLOCK-PRINTED RUFFLED CUSHION COVER - GARNET RED DOT & GRID', '<p>Inspired by the charm of country living, this ruffled cushion cover adds a soft, timeless touch to your home. Featuring beautiful hand block printed patterns on 100% cotton, each piece is handcrafted and celebrates the beauty of traditional craftsmanship.<br />\n<br />\nFinished with delicate ruffled edges, it brings a cozy, vintage-inspired look to sofas, beds, and accent chairs. Handmade in small batches, each cushion cover is unique, combining everyday comfort with artisanal charm.<br />\n<br />\nDetails:<br />\n<br />\n• Size: 12&quot; x 16&quot;<br />\n• Material: 100% Cotton<br />\n• Closure: Concealed zipper for a neat, seamless finish<br />\n<br />\nCare Instructions: Machine wash cold on a gentle cycle with like colors. Lay flat to dry or tumble dry on a low setting. Iron on the reverse side if needed.<br />\n<br />\nMade in India</p>', 'ready', 'BLOCK-PRINTED RUFFLED CUSHION COVER - GARNET RED DOT & GRID', 'Inspired by the charm of country living, this ruffled cushion cover adds a soft, timeless touch to your home. Featuring beautiful hand block printed patterns on 100% cotton, each piece is handcrafted and celebrates the beauty of traditional craftsmanship.', 'Throw Pillow Cover'),
